import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0028 — Excalidraw: fork con lazo, secchiello e disegna per la forma","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0028-excalidraw-fork.md","filePath":"adr/0028-excalidraw-fork.md"}'),d={name:"adr/0028-excalidraw-fork.md"};function c(r,e,l,n,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0028-—-excalidraw-fork-con-lazo-secchiello-e-disegna-per-la-forma" tabindex="-1">ADR-0028 — Excalidraw: fork con lazo, secchiello e disegna per la forma <a class="header-anchor" href="#adr-0028-—-excalidraw-fork-con-lazo-secchiello-e-disegna-per-la-forma" aria-label="Permalink to &quot;ADR-0028 — Excalidraw: fork con lazo, secchiello e disegna per la forma&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.7.3, §4.2, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-29</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>ADR-0003, ADR-0024 (limiti noti: Scribble Helper), ADR-0025 (build esbuild)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì: dipendenza <code>@zsviczian/excalidraw</code> al posto di <code>@excalidraw/excalidraw</code> 0.18.1</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> La dipendenza sta ora in <code>packages/workbench/package.json</code> (frontend condiviso da desktop e workbench web, ADR-0029), con lo stesso alias <code>npm:@zsviczian/excalidraw@0.18.145</code>; la copia dello script è fatta da <code>copyExcalidrawAssets</code>, condivisa dalle build di desktop e web.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il plugin Excalidraw di terze parti, per editor di note Markdown, offre <em>Disegna per la forma</em> (Shift+X), <em>Secchiello riempimento</em> (B) e <em>Selezione a lazo</em>. Excalidraw upstream 0.18.1 non li ha (nessun tool <code>lasso</code>, <code>bucketfill</code>, <code>autoshape</code>). Il plugin usa il fork <code>@zsviczian/excalidraw</code> (MIT), che li include.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><code>apps/desktop/frontend/package.json</code>: <code>&quot;@excalidraw/excalidraw&quot;: &quot;npm:@zsviczian/excalidraw@0.18.145&quot;</code> (alias npm: gli import restano invariati).</li><li>Il dist/prod del fork non è autocontenuto; l&#39;unica build completa è uno script classico (<code>excalidraw.production.min.js</code>, in una sottocartella di <code>dist/</code> del pacchetto) che legge <code>React</code>, <code>ReactDOM</code> e <code>ReactJSXRuntime</code> dai globali. <code>scripts/esbuild.mjs</code> (plugin <code>excalidraw-fork</code>) lo copia in <code>dist/excalidraw-assets/excalidraw.js</code>, lo carica con un tag <code>&lt;script&gt;</code> (stessa origine, compatibile con <code>script-src &#39;self&#39;</code>, offline) e lo riesporta per nome (<code>scripts/excalidraw-exports.json</code>, da rigenerare se cambiano gli export del fork). Il CSS è quello della stessa build del fork.</li><li><code>drawing/ExcalidrawIsland.tsx</code> monta l&#39;editor in una root React propria: il fork non regge il doppio mount di <code>&lt;StrictMode&gt;</code> in sviluppo.</li><li>Adattamenti all&#39;API del fork: <code>onExcalidrawAPI</code>, <code>setViewport</code> al posto di <code>scrollToContent</code>, binding delle frecce <code>{ elementId, fixedPoint, mode }</code> (<code>actions/factory.ts</code>), tipi mappati in <code>tsconfig.app.json</code>.</li><li>Menu e comandi di Excalidraw al 90% (variabili CSS dei pulsanti/icone in <code>style.css</code>); rimosso il pulsante del menu principale.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Implementazione custom su 0.18.1</strong> — meno fedele al plugin, tre strumenti da mantenere.</li><li><strong>Solo voci segnaposto</strong> — non funzionanti.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>+ Strumenti identici al plugin; Scribble Helper (ADR-0024) coperto da <em>Disegna per la forma</em>.</li><li>− Script di 6,5 MB servito come asset (fuori dal budget del bundle); fork con release proprie, da pinnare e riverificare a ogni aggiornamento (e2e <code>drawing*</code>, merge fixture <code>excalidraw-*</code>).</li><li>− Struttura DOM diversa (<code>.App-top-bar</code>, <code>.App-bottom-bar</code>): selettori CSS/e2e aggiornati.</li></ul>',11)])])}const g=o(d,[["render",c]]);export{m as __pageData,g as default};
